// Helper Functions
window.RadarHelpers = {
  formatRupiah(num) {
    if (num === null || num === undefined || isNaN(num)) return "Rp -";
    return "Rp " + Math.round(num).toLocaleString("id-ID");
  },

  formatNumber(num) {
    if (num === null || num === undefined || isNaN(num)) return "0";
    return Number(num).toLocaleString("id-ID");
  },

  formatPercent(pct) {
    if (pct === null || pct === undefined || isNaN(pct)) return "0.0%";
    const sign = pct > 0 ? "+" : "";
    return sign + Number(pct).toFixed(1) + "%";
  },

  getStatusMeta(statusKey) {
    switch (statusKey) {
      case "bawah":
        return {
          label: "Di Bawah Acuan",
          code: "bawah",
          desc: "Harga lebih dari 5% di bawah HAP pemerintah (pasokan melimpah)",
          colorHex: "#2E7D32",
          bgHex: "#E8F5E9",
          badgeClass: "badge-status-bawah"
        };
      case "sesuai":
        return {
          label: "Sesuai Rentang Acuan",
          code: "sesuai",
          desc: "Harga berada dalam rentang kewajaran ±5% HAP",
          colorHex: "#0D9488",
          bgHex: "#F0FDFA",
          badgeClass: "badge-status-sesuai"
        };
      case "atas":
        return {
          label: "Sedikit di Atas Acuan",
          code: "atas",
          desc: "Harga berada 5% - 15% di atas acuan resmi pemerintah",
          colorHex: "#D97706",
          bgHex: "#FEF3C7",
          badgeClass: "badge-status-atas"
        };
      case "tinggi":
        return {
          label: "Disparitas Tinggi",
          code: "tinggi",
          desc: "Harga lebih dari 15% di atas acuan wajar (pantauan intensif)",
          colorHex: "#B91C1C",
          bgHex: "#FEE2E2",
          badgeClass: "badge-status-tinggi"
        };
      default:
        return {
          label: "Terkonfirmasi Wajar",
          code: "netral",
          desc: "Data harga terverifikasi",
          colorHex: "#475569",
          bgHex: "#F1F5F9",
          badgeClass: "badge-status-netral"
        };
    }
  }
};
